#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
install_wave1.py - the whole of SIREN wave 1, in one pass, on a fresh copy of the app.

This is the integrated form of four separately-authored patch sets plus the defects that
only appear once they sit together:

  present-copy        the client-facing title, the "N of M" count, 5px tile titles, the
                      checkpoint card's type scale, the LR sliver on the Map
  present-controls    14 bar controls folded to 7 on one row, the Studio sidebar led by the
                      presenter's own tools, one branch chooser, a visible route delete
  present-a11y        the Present overlay as a real modal dialog, a focusable tile control,
                      a step list you can enter, a keyboard card, palette and toast fixes
  preview             the five unclickable workspace controls, the zoom chip and popover,
                      auto re-fit, one-row toolbar and header, the selection bar
  wave1-integration   four defects measured only in the integrated build, plus three
                      changes taken from the design critique of the reworked Present mode

Three anchors had to be re-cut because an earlier phase had already rewritten the text a
later phase was looking for; those are resolved in this file, in this order. Running the
four original scripts in sequence no longer works and should not be attempted.

Usage:  python install_wave1.py <path-to-T_Industries_SIREN_v1.html>

Every replacement asserts its occurrence count BEFORE it runs, so a moved anchor - or a
second run over an already-patched file - fails loudly and writes nothing. The write is
atomic (tmp in the target's own directory + os.replace).
"""

import io
import os
import sys
import tempfile

PANEL_START = '          <details class="present-panel"'
PANEL_END = '\n          </details>\n'


def cut_panel(text, summary):
    """Lift one <details> panel out of the Studio sidebar, by its summary."""
    needle = '<summary>%s</summary>' % summary
    if text.count(needle) != 1:
        raise SystemExit('ABORT: expected exactly 1 "%s" panel, found %d' % (summary, text.count(needle)))
    marker = text.index(needle)
    start = text.rindex(PANEL_START, 0, marker)
    end = text.index(PANEL_END, marker) + len(PANEL_END)
    return text[:start] + text[end:], text[start:end]


def reorder_sidebar(text):
    """A presenter opens the Studio to read their notes and reach the laser pointer. Both
    started four panels and 52 editing controls below the fold; now they lead."""
    text, notes = cut_panel(text, 'Presenter notes')
    text, playback = cut_panel(text, 'Playback & live tools')
    anchor = '          <details class="present-panel" open>\n            <summary>Navigator & sequence</summary>\n'
    if text.count(anchor) != 1:
        raise SystemExit('ABORT: expected exactly 1 open "Navigator & sequence" panel, found %d' % text.count(anchor))
    # Playback opens too - the laser, spotlight, pen and Clear drawings are live tools.
    playback = playback.replace('<details class="present-panel">', '<details class="present-panel" open>', 1)
    # The navigator is authoring. It stays reachable, one press below the live tools.
    closed = anchor.replace('<details class="present-panel" open>', '<details class="present-panel">')
    return text.replace(anchor, notes + playback + closed, 1)


