def main():
    # A Windows console defaults to cp1252 and would die on the glyphs in these labels
    # before it ever got to the file. Progress output must never be what breaks the patch.
    try:
        sys.stdout.reconfigure(encoding='utf-8', errors='replace')
    except Exception:
        pass
    if len(sys.argv) < 2:
        print('usage: python install_wave1.py <path-to-app.html>', file=sys.stderr)
        return 2
    target = os.path.abspath(sys.argv[1])
    with io.open(target, 'r', encoding='utf-8', newline='') as handle:
        text = handle.read()
    original = text
    applied = 0

    for phase, edits in PHASES:
        if edits is None:
            text = reorder_sidebar(text)
            print('== sidebar reorder ==')
            print('  ok  Presenter notes and Playback & live tools lead; Navigator closes')
            continue
        print('== %s (%d edits) ==' % (phase, len(edits)))
        for name, old, new, count in edits:
            found = text.count(old)
            if found != count:
                print('ABORT [%s / %s]: expected %d occurrence(s) of the anchor, found %d. '
                      'Nothing was written.' % (phase, name, count, found), file=sys.stderr)
                return 1
            text = text.replace(old, new, count)
            applied += 1
            print('  ok  %s' % name)

    if text == original:
        print('ABORT: nothing changed.', file=sys.stderr)
        return 1

    directory = os.path.dirname(target) or '.'
    handle = tempfile.NamedTemporaryFile('w', encoding='utf-8', newline='', dir=directory,
                                         prefix='.siren-wave1-', suffix='.tmp', delete=False)
    try:
        handle.write(text)
        handle.flush()
        os.fsync(handle.fileno())
        handle.close()
        os.replace(handle.name, target)
    except BaseException:
        handle.close()
        if os.path.exists(handle.name):
            os.unlink(handle.name)
        raise

    print('wrote %s (%d -> %d bytes, %d string edits + 1 sidebar reorder)'
          % (target, len(original.encode('utf-8')), len(text.encode('utf-8')), applied))
    return 0


if __name__ == '__main__':
    sys.exit(main())
